//! The theme documents of the crate as embedded assets, with the feature
//! `document-assets` and in the tests of the crate.
//!
//! The table is generated by the build script of the crate from the files
//! under `Themes/` (the counterpart of the embedded resources of the
//! upstream project file), which it also compiles: the styles of the library
//! are loaded from their compiled markup, and the assets are what lets a
//! document the run-time loader loads include them (`build.rs`).

use crate::ASSEMBLY;
use ferroui_base::platform::register_assets;

include!(concat!(env!("OUT_DIR"), "/assets.rs"));

/// Registers the embedded assets with the asset loader under the name of
/// the assembly of the crate.
pub(crate) fn register() {
    register_assets(ASSEMBLY.name, ASSETS);
}
